function r2(x){ return Math.round(x*100)/100; }
function detectSilence(samples, sr, opts){
  opts=opts||{};
  var thDb=(typeof opts.thresholdDb==='number')?opts.thresholdDb:-50;
  var minSil=(typeof opts.minSilenceSec==='number')?opts.minSilenceSec:0.3;
  var pad=(typeof opts.padSec==='number')?opts.padSec:0.05;
  var n=samples? samples.length:0;
  if(!n||!sr||sr<=0) return {error:'缺少采样数据'};
  var th=Math.pow(10, thDb/20);
  var silent=new Array(n);
  for(var i=0;i<n;i++) silent[i]=Math.abs(samples[i])<th;
  var runs=[], s=-1;
  for(var k=0;k<=n;k++){
    var isS=(k<n)&&silent[k];
    if(isS&&s<0)s=k;
    if(!isS&&s>=0){ runs.push({start:s, end:k}); s=-1; }
  }
  var kept=runs.filter(function(r){ return (r.end-r.start)/sr>=minSil; });
  var totalSil=0;
  kept.forEach(function(r){ totalSil+=(r.end-r.start)/sr; });
  var dur=n/sr;
  var segments=[], cur=0;
  kept.forEach(function(r){
    if(r.start>cur) segments.push({start:cur, end:r.start});
    cur=Math.max(cur, r.end);
  });
  if(cur<n) segments.push({start:cur, end:n});
  var firstNon=0; while(firstNon<n&&silent[firstNon])firstNon++;
  var lastNon=n-1; while(lastNon>=0&&silent[lastNon])lastNon--;
  var trim=null;
  if(firstNon<n){
    var ts=Math.max(0, Math.round((firstNon/sr-pad)*1000));
    var te=Math.min(Math.round(dur*1000), Math.round(((lastNon+1)/sr+pad)*1000));
    trim={startMs:ts, endMs:te, savesMs:Math.round(dur*1000-(te-ts))};
  }
  return {
    durationSec:r2(dur), thresholdDb:thDb, minSilenceSec:minSil,
    runs:kept.map(function(r){
      return {startMs:Math.round(r.start/sr*1000), endMs:Math.round(r.end/sr*1000), durSec:r2((r.end-r.start)/sr)};
    }),
    silenceTotalSec:r2(totalSil), silenceRatio:r2(totalSil/dur),
    segments:segments.map(function(g){
      return {startMs:Math.round(g.start/sr*1000), endMs:Math.round(g.end/sr*1000), durSec:r2((g.end-g.start)/sr)};
    }),
    trim:trim, allSilent:firstNon>=n
  };
}
var EXPORTS={detectSilence:detectSilence};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.SilenceForgePure = EXPORTS; }
